from typing import Dict, Any, Optional


@dataclass
class StorageConfig:
    region: str
    bucket: str


@dataclass
class UploadPayload:
    object_name: str
    data: Any
    content_type: Optional[str] = None


@dataclass
class DownloadRequest:
    object_name: str
    expires_in: int = 3600  # Seconds


